mapper.update:
UPDATE app.fait_parti
SET etat = #{etat}
WHERE cip = #{cip}
  AND discussion_id = #{discussionId}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM app.fait_parti fp
    WHERE fp.cip = #{blockerCip}
      AND fp.etat = 'blocked'
      AND fp.discussion_id IN (
          SELECT fp2.discussion_id
          FROM app.fait_parti fp2
          LEFT JOIN app.equipe e ON e.discussion_id = fp2.discussion_id
          WHERE fp2.cip = #{blockedCip}
            AND e.equipe_id IS NULL
            AND (SELECT COUNT(*) FROM app.fait_parti fp3 WHERE fp3.discussion_id = fp2.discussion_id) = 2
      )
)

SELECT EXISTS (
    SELECT 1 FROM app.fait_parti
    WHERE discussion_id = #{discussionId}
      AND cip = #{cip}
)
